from datetime import date


def _datediff(d1: str, d2: str) -> int:
    """Return whole calendar days d1 - d2 using legacy sentinel semantics."""
    if not d1 or not d2 or d1 == "00000000" or d2 == "00000000":
        return 0

    def parse(value: str) -> date:
        if len(value) != 8 or not value.isdigit():
            raise ValueError(f"Invalid YYYYMMDD date: {value!r}")
        return date(int(value[0:4]), int(value[4:6]), int(value[6:8]))

    return (parse(d1) - parse(d2)).days


def escalate(cases: list[dict], today: str) -> list[dict]:
    """Return auto-escalation workflow events in ascending CASE_ID order."""
    events: list[dict] = []

    for case in sorted(cases, key=lambda row: str(row.get("CASE_ID", ""))):
